package com.nm.fragmentsclean.userApplicationContext.write.businesslogic.usecases;

import com.nm.fragmentsclean.sharedKernel.businesslogic.commandStatus.BusinessCommandRejectedException;import com.nm.fragmentsclean.sharedKernel.businesslogic.media.PrivateMediaReferences;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.*;import com.nm.fragmentsclean.sharedKernel.businesslogic.models.command.CommandHandler;import com.nm.fragmentsclean.userApplicationContext.write.businesslogic.gateways.*;import jakarta.transaction.Transactional;

public class ConfirmAvatarCommandHandler implements CommandHandler<ConfirmAvatarCommand>{private final AppUserRepository users;private final AvatarMediaRepository media;private final DomainEventPublisher events;private final DateTimeProvider clock;public ConfirmAvatarCommandHandler(AppUserRepository users,AvatarMediaRepository media,DomainEventPublisher events,DateTimeProvider clock){this.users=users;this.media=media;this.events=events;this.clock=clock;}@Override@Transactional public void execute(ConfirmAvatarCommand command){var user=users.findById(command.userId()).orElseThrow(()->new BusinessCommandRejectedException("APP_USER_NOT_FOUND","User not found"));var item=media.byId(command.mediaId()).orElseThrow(()->new BusinessCommandRejectedException("AVATAR_NOT_FOUND","Avatar upload intent does not exist"));item.requireOwner(command.userId());var now=clock.now();boolean confirmed=item.confirm(command.objectKey(),command.contentType(),command.size(),command.width(),command.height(),command.sha256(),now);if(!confirmed)return;var previous=media.activeByUser(command.userId()).filter(active->!active.id().equals(item.id()));if(previous.isPresent()){var active=previous.get();active.requestDeletion(now);media.replaceActive(active,item);}else media.save(item);if(user.replaceAvatar(PrivateMediaReferences.avatar(command.objectKey()),now)){users.save(user);user.domainEvents().forEach(events::publish);user.clearDomainEvents();}}}
